<?php require 'db.php'; if(current_user()){header('Location: profile.php');exit;} $error=null; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pw=$_POST['password']??'';$confirm=$_POST['confirm_password']??'';if($name===''||!preg_match('/^[A-Za-z\s.\'-]{2,100}$/',$name))$error='Please enter a valid name.';elseif(!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Please enter a valid email address.';elseif(strlen($pw)<8||!preg_match('/[A-Z]/',$pw)||!preg_match('/[a-z]/',$pw)||!preg_match('/\d/',$pw))$error='Password must be 8+ characters and include uppercase, lowercase and a number.';elseif($pw!==$confirm)$error='Passwords do not match.';else{$s=$pdo->prepare('SELECT user_id FROM users WHERE email=?');$s->execute([$email]);if($s->fetch())$error='Unable to create the account with these details. Please try another email.';else{$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,"customer")');$s->execute([$name,$email,password_hash($pw,PASSWORD_BCRYPT)]);$uid=(int)$pdo->lastInsertId();$s=$pdo->prepare('INSERT INTO profiles(user_id) VALUES(?)');$s->execute([$uid]);$pdo->commit();$s=$pdo->prepare('SELECT * FROM users WHERE user_id=?');$s->execute([$uid]);login_user($s->fetch());$to=$_SESSION['return_to']??'profile.php';unset($_SESSION['return_to']);header('Location: '.$to);exit;}}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create Account | Ceylon Spice Hub</title><link rel="stylesheet" href="style.css"></head><body><header class="header"><div class="container nav-wrap"><a class="brand" href="index.php"><span>Ceylon</span><small>SPICE HUB</small></a><a href="index.php" class="text-link">← Back to shop</a></div></header><main class="auth-page"><div class="auth-card"><p class="eyebrow">JOIN CEYLON SPICE HUB</p><h1>Create your account</h1><p class="muted">Save your details, manage your profile and keep your orders together.</p><?php if($error):?><div class="form-error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Full Name<input name="name" value="<?=e($_POST['name']??'')?>" required></label><label>Email Address<input type="email" name="email" value="<?=e($_POST['email']??'')?>" required></label><label>Password<input type="password" name="password" required minlength="8"><small class="hint">8+ characters, uppercase, lowercase and number.</small></label><label>Confirm Password<input type="password" name="confirm_password" required></label><button class="btn btn-primary auth-submit">CREATE ACCOUNT</button></form><p class="auth-switch">Already have an account? <a href="login.php">Log in</a></p></div></main></body></html>